#include <iostream>
#include <algorithm>
#include <string>
using namespace std;

using i128 = __int128_t;

void print128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string s;
    while (value > 0) {
        s.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long xx, yy, mm;
    cin >> xx >> yy >> mm;

    i128 x = xx, y = yy, m = mm;
    i128 operations = 0;

    if (x >= m || y >= m) {
        cout << 0 << '\n';
        return 0;
    }

    if (x <= 0 && y <= 0) {
        cout << -1 << '\n';
        return 0;
    }

    if (x < y)
        swap(x, y);

    if (y < 0) {
        i128 steps = (-y + x - 1) / x;
        y += steps * x;
        operations += steps;
    }

    while (x < m && y < m) {
        if (x < y)
            x += y;
        else
            y += x;
        ++operations;
    }

    print128(operations);
    cout << '\n';
    return 0;
}

